import{_ as t,o,c as s,ao as l}from"./chunks/framework.liXUzqYA.js";const u=JSON.parse('{"title":"CTModels.jl","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),i={name:"index.md"};function a(n,e,d,r,c,p){return o(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="CTModels.jl" tabindex="-1">CTModels.jl <a class="header-anchor" href="#CTModels.jl" aria-label="Permalink to &quot;CTModels.jl {#CTModels.jl}&quot;">​</a></h1><p><code>CTModels.jl</code> is the <strong>model layer</strong> of the <a href="https://github.com/control-toolbox" target="_blank" rel="noreferrer">control-toolbox</a> ecosystem. It defines how an optimal control problem (OCP), its numerical solution and an initial guess are represented, and nothing else: it neither parses, discretises nor solves.</p><div class="tip custom-block"><p class="custom-block-title">Who this documentation is for</p><p>This site documents CTModels for <strong>developers</strong> of the control-toolbox packages and for <strong>experienced users</strong> who work with the model objects directly. To model and solve optimal control problems, start with <a href="https://control-toolbox.org/OptimalControl.jl" target="_blank" rel="noreferrer">OptimalControl.jl</a>, which wraps CTModels behind the <code>@def</code> DSL and <code>solve</code>.</p></div><h2 id="Place-in-the-ecosystem" tabindex="-1">Place in the ecosystem <a class="header-anchor" href="#Place-in-the-ecosystem" aria-label="Permalink to &quot;Place in the ecosystem {#Place-in-the-ecosystem}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   CTParser ── @def ──► PreModel ── build ──► Model ◄──────────────────┐</span></span>
<span class="line"><span>                        (CTModels.Building)   (CTModels.Models)        │</span></span>
<span class="line"><span>                                                │                      │</span></span>
<span class="line"><span>                         CTDirect (direct) ─────┤                      │</span></span>
<span class="line"><span>                         CTFlows (indirect) ────┤                      │</span></span>
<span class="line"><span>                                                ▼                      │</span></span>
<span class="line"><span>                    solver output ── build_solution ──► Solution ──────┘</span></span>
<span class="line"><span>                                    (CTModels.Solutions)  │</span></span>
<span class="line"><span>                                                          ├─► Init (warm start)</span></span>
<span class="line"><span>                                                          ├─► Serialization (JSON, JLD2)</span></span>
<span class="line"><span>                                                          └─► PlotCase ─► Plots / Makie</span></span></code></pre></div><ul><li><p><a href="https://github.com/control-toolbox/CTParser.jl" target="_blank" rel="noreferrer">CTParser.jl</a> turns the <code>@def</code> DSL into calls to the <code>Building</code> verbs (<code>state!</code>, <code>dynamics!</code>, <code>constraint!</code>, …) and <code>build</code>.</p></li><li><p><a href="https://github.com/control-toolbox/CTDirect.jl" target="_blank" rel="noreferrer">CTDirect.jl</a> discretises a <code>Model</code> into an NLP and turns the NLP solution back into a <code>Solution</code> with <code>build_solution</code>.</p></li><li><p><a href="https://github.com/control-toolbox/CTFlows.jl" target="_blank" rel="noreferrer">CTFlows.jl</a> builds Hamiltonian flows from a <code>Model</code> and returns <code>Solution</code> objects as well.</p></li><li><p><a href="https://github.com/control-toolbox/CTSolvers.jl" target="_blank" rel="noreferrer">CTSolvers.jl</a> provides the resolution infrastructure (NLP solvers, modelers, ODE integrators) used by CTDirect and CTFlows.</p></li><li><p><a href="https://github.com/control-toolbox/OptimalControl.jl" target="_blank" rel="noreferrer">OptimalControl.jl</a> re-exports a selection of CTModels symbols for end users.</p></li></ul><h2 id="Modules" tabindex="-1">Modules <a class="header-anchor" href="#Modules" aria-label="Permalink to &quot;Modules {#Modules}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Module</th><th style="text-align:right;">Responsibility</th></tr></thead><tbody><tr><td style="text-align:right;"><code>CTModels.Components</code></td><td style="text-align:right;">Component types (state, control, variable, times, objective, constraints) and their accessors</td></tr><tr><td style="text-align:right;"><code>CTModels.Models</code></td><td style="text-align:right;">The immutable <code>Model</code> and its accessors</td></tr><tr><td style="text-align:right;"><code>CTModels.Building</code></td><td style="text-align:right;">The mutable <code>PreModel</code>, the declaration verbs (<code>state!</code>, <code>dynamics!</code>, …) and <code>build</code></td></tr><tr><td style="text-align:right;"><code>CTModels.Solutions</code></td><td style="text-align:right;"><code>Solution</code>, <code>build_solution</code>, time grids, dual model, solver infos</td></tr><tr><td style="text-align:right;"><code>CTModels.Init</code></td><td style="text-align:right;">Initial guesses: input formats, validation, warm start</td></tr><tr><td style="text-align:right;"><code>CTModels.Display</code></td><td style="text-align:right;"><code>Base.show</code> for models, pre-models, components and solutions</td></tr><tr><td style="text-align:right;"><code>CTModels.Serialization</code></td><td style="text-align:right;"><code>export_ocp_solution</code> / <code>import_ocp_solution</code> (implemented by extensions)</td></tr><tr><td style="text-align:right;"><code>CTModels.PlotCase</code></td><td style="text-align:right;">Backend-free description of the solution figure (rendered by the plotting extensions)</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:right;">Extension</th><th style="text-align:right;">Trigger package</th><th style="text-align:right;">Adds</th></tr></thead><tbody><tr><td style="text-align:right;"><code>CTModelsJSON</code></td><td style="text-align:right;"><code>JSON3</code></td><td style="text-align:right;">JSON export and import of a <code>Solution</code></td></tr><tr><td style="text-align:right;"><code>CTModelsJLD</code></td><td style="text-align:right;"><code>JLD2</code></td><td style="text-align:right;">JLD2 export and import of a <code>Solution</code></td></tr><tr><td style="text-align:right;"><code>CTModelsPlots</code></td><td style="text-align:right;"><code>Plots</code></td><td style="text-align:right;"><code>Plots.plot(sol)</code> / <code>Plots.plot!(sol)</code></td></tr><tr><td style="text-align:right;"><code>CTModelsMakie</code></td><td style="text-align:right;"><code>Makie</code> (via <code>CairoMakie</code>, <code>GLMakie</code>, …)</td><td style="text-align:right;"><code>Makie.plot(sol)</code> / <code>Makie.plot!(fig, sol)</code></td></tr></tbody></table><h2 id="Conventions" tabindex="-1">Conventions <a class="header-anchor" href="#Conventions" aria-label="Permalink to &quot;Conventions {#Conventions}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Qualified access</p><p>CTModels exports no symbol at the package level. Each submodule exports its public API and the package brings the submodules in, so every public symbol is reached as <code>CTModels.symbol</code>, for example <code>CTModels.state!</code> or <code>CTModels.build_solution</code>; this is the form used throughout this documentation. The fully qualified form <code>CTModels.Building.state!</code> refers to the same function.</p></div><ul><li><p><strong>One-dimensional is scalar.</strong> A one-dimensional state, control or variable is a <code>Number</code>, never a length-1 vector: user functions receive <code>u</code>, not <code>u[1]</code>, and solution and initial-guess trajectories return scalars.</p></li><li><p><strong>In-place functions.</strong> Dynamics and nonlinear constraints are written in place, <code>f!(r, t, x, u, v)</code> and <code>b!(r, x0, xf, v)</code>, with the full argument list even for an autonomous problem.</p></li><li><p><strong>Structured errors.</strong> Invalid inputs raise the typed exceptions of <code>CTBase.Exceptions</code> (<code>IncorrectArgument</code>, <code>PreconditionError</code>, <code>ExtensionError</code>, …), with a message, the received and expected values, and a hint.</p></li></ul><h2 id="How-this-documentation-is-organised" tabindex="-1">How this documentation is organised <a class="header-anchor" href="#How-this-documentation-is-organised" aria-label="Permalink to &quot;How this documentation is organised {#How-this-documentation-is-organised}&quot;">​</a></h2><ul><li><p><a href="./getting-started">Getting started</a>: a model, a solution and an initial guess in five minutes.</p></li><li><p><strong>OCP model</strong>: the <code>PreModel → build → Model</code> pipeline, the type and trait architecture, each declaration verb, and the display of models.</p></li><li><p><strong>Solutions</strong>: the anatomy of a <code>Solution</code>, the <a href="./solution/build_solution"><code>build_solution</code> contract</a> for solver authors, time grids, trajectories, duals and diagnostics.</p></li><li><p><strong>Initial guesses</strong>: input formats, validation and warm start.</p></li><li><p><strong>Extensions</strong>: export and import, plotting with Plots and Makie, and the <a href="./serialization/plotcase">plotting architecture</a>.</p></li><li><p><a href="./guide/performance">Performance</a>: the hot path / setup path rule and how type stability is checked.</p></li><li><p><strong>API Reference</strong>: one page of public symbols per submodule, and one page of internals (private symbols and extensions).</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Ask DeepWiki</p><p><a href="https://deepwiki.com/control-toolbox/CTModels.jl" target="_blank" rel="noreferrer"><img src="https://deepwiki.com/badge.svg" alt="Ask DeepWiki"></a> offers an interactive, AI-generated overview of this codebase. Answers may be inaccurate: this documentation is the reference.</p></div>`,15)])])}const g=t(i,[["render",a]]);export{u as __pageData,g as default};
